<script setup>import {Head,Link,router,usePage} from '@inertiajs/vue3';import AdminShell from '../../Components/AdminShell.vue';defineProps({metrics:Object,notifications:Array,recentOrders:Array});const page=usePage();const base=page.props.adminPanel?.base_path||'/admin';const labels={orders_today:'Pesanan Hari Ini',revenue_today:'Omzet Hari Ini',success_today:'Pesanan Berhasil',open_tickets:'Tiket Terbuka',pending_fulfillment:'Pending Fulfillment',wallet_balance:'Saldo Wallet'};const money=(k,v)=>(k.includes('revenue')||k.includes('wallet'))?'Rp'+Number(v||0).toLocaleString('id-ID'):v;</script>
<template><Head title="Panel Admin"/><AdminShell><div class="flex items-start justify-between gap-3"><div><h1 class="m-0 text-[25px] font-black tracking-[-.04em]">Panel Admin LFAMILIA STORE</h1><p class="mt-1 text-[10px] text-slate-500">Kelola seluruh operasional toko dari satu workspace.</p></div><button class="rounded-md border border-slate-200 bg-white px-3 py-2 text-[9px] font-semibold" @click="router.post(base+'/logout')">Keluar</button></div><section class="lf-metrics"><article v-for="(v,k) in metrics" :key="k" class="lf-metric"><span>{{k==='revenue_today'?'Rp':k==='orders_today'?'🛒':k==='success_today'?'✓':k==='open_tickets'?'?':k==='pending_fulfillment'?'↻':'◈'}}</span><div><small>{{labels[k]||k}}</small><strong>{{money(k,v)}}</strong></div></article></section><div class="lf-admin-grid"><section class="lf-admin-panel"><header><h2 class="text-[11px] font-extrabold">Aktivitas Terbaru</h2></header><div v-if="!recentOrders?.length" class="p-8 text-center text-slate-400">Belum ada pesanan yang dapat ditampilkan.</div><article v-for="order in recentOrders" :key="order.id"><Link :href="base + '/orders/' + order.id" class="font-semibold text-blue-600">{{order.order_number}}</Link><p>{{order.status}} · Rp{{Number(order.total_idr).toLocaleString('id-ID')}} · {{order.created_at}}</p></article></section><section class="lf-admin-panel"><header><h2 class="text-[11px] font-extrabold">Notifikasi terbaru</h2><a :href="base+'/notifications'" class="text-[8px] font-bold text-[#1769e8]">Lihat semua</a></header><div v-if="!notifications.length" class="p-8 text-center text-[9px] text-slate-400">Belum ada notifikasi.</div><article v-for="n in notifications" :key="n.id"><strong>{{n.title}} · {{n.severity}}</strong><p>{{n.message}}</p></article></section></div></AdminShell></template>